# Get non-empty, non-comment lines
lines = [line.strip() for line in student_code.split('\n') if line.strip() and not line.strip().startswith('#')]

# Task 1: Check import
if not any('from bs4 import BeautifulSoup' in line for line in lines):
    raise AssertionError('Task 1: Missing "from bs4 import BeautifulSoup"')

# Task 2: Check BeautifulSoup() call
if not any('soup' in line and 'BeautifulSoup' in line and 'html.parser' in line for line in lines):
    raise AssertionError("Task 2: soup should use BeautifulSoup() with 'html.parser'")

# Task 3: Check find by ID
if not any("find(id='main-title')" in line or 'find(id="main-title")' in line for line in lines):
    raise AssertionError("Task 3: Should use soup.find(id='main-title')")
if not any('main_title' in line and '.text' in line and 'print' in line for line in lines):
    raise AssertionError('Task 3: Should print main_title.text')

# Task 4: Check find_all by class
if not any("find_all(class_='product-name')" in line or 'find_all(class_="product-name")' in line for line in lines):
    raise AssertionError("Task 4: Should use soup.find_all(class_='product-name')")

# Task 5: Check loop and text printing (flexible format)
if 'for name in product_names:' not in student_code:
    raise AssertionError('Task 5: Should loop through product_names')
if not any(('print' in line and 'name' in line and '.text' in line) for line in lines):
    raise AssertionError('Task 5: Should print name.text inside the loop (simple or f-string)')

print('TEST_PASSED')
